def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    line = next(v for v in set(sum(g, [])) if v != 9)
    # Flood from the border through background, including diagonals; enclosed
    # background pockets are recolored.
    seen = set()
    stack = []
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and g[r][c] != line:
                seen.add((r, c))
                stack.append((r, c))
    while stack:
        r, c = stack.pop()
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                y, x = r + dr, c + dc
                if 0 <= y < h and 0 <= x < w and (y, x) not in seen and g[y][x] != line:
                    seen.add((y, x))
                    stack.append((y, x))
    for r in range(h):
        for c in range(w):
            if g[r][c] == 9 and (r, c) not in seen:
                g[r][c] = 4
    return g

